  1→import { showToast } from "~/utils/toast";
  2→import { useState, useCallback, useEffect } from "react";
  3→import {
  4→  data,
  5→  type ActionFunctionArgs,
  6→  type HeadersFunction,
  7→  type LoaderFunctionArgs,
  8→} from "react-router";
  9→import { useLoaderData, useActionData, useFetcher } from "react-router";
 10→import {
 11→  Page,
 12→  Layout,
 13→  Card,
 14→  Text,
 15→  InlineStack,
 16→  BlockStack,
 17→  Badge,
 18→  Button,
 19→  Box,
 20→  Divider,
 21→  TextField,
 22→  Select,
 23→  Checkbox,
 24→  EmptyState,
 25→  SkeletonPage,
 26→  SkeletonBodyText,
 27→  Modal,
 28→  FormLayout,
 29→  IndexTable,
 30→  useIndexResourceState,
 31→} from "@shopify/polaris";
 32→import { authenticate } from "../shopify.server";
 33→import { boundary } from "@shopify/shopify-app-react-router/server";
 34→import db from "../db.server";
 35→
 36→// ─── Types ────────────────────────────────────────────────────────────────────
 37→
 38→interface ResultPageData {
 39→  id: string;
 40→  quizId: string;
 41→  title: string;
 42→  description: string | null;
 43→  type: string;
 44→  minScore: number | null;
 45→  maxScore: number | null;
 46→  matchTags: string[];
 47→  productLimit: number;
 48→  layout: string;
 49→  showDiscount: boolean;
 50→  discountType: string | null;
 51→  discountValue: number | null;
 52→  discountCode: string | null;
 53→  ctaText: string | null;
 54→  ctaUrl: string | null;
 55→  styling: Record<string, unknown>;
 56→  position: number;
 57→  createdAt: string;
 58→  updatedAt: string;
 59→}
 60→
 61→interface QuizSummary {
 62→  id: string;
 63→  title: string;
 64→  status: string;
 65→}
 66→
 67→interface LoaderData {
 68→  quiz: QuizSummary;
 69→  resultPages: ResultPageData[];
 70→}
 71→
 72→// ─── Helpers ──────────────────────────────────────────────────────────────────
 73→
 74→function parseSafe<T>(str: string, fallback: T): T {
 75→  try {
 76→    return JSON.parse(str) as T;
 77→  } catch {
 78→    return fallback;
 79→  }
 80→}
 81→
 82→const typeOptions = [
 83→  { label: "Default", value: "default" },
 84→  { label: "Score Range", value: "score-range" },
 85→  { label: "Tag Match", value: "tag-match" },
 86→];
 87→
 88→const layoutOptions = [
 89→  { label: "Grid", value: "grid" },
 90→  { label: "List", value: "list" },
 91→  { label: "Carousel", value: "carousel" },
 92→];
 93→
 94→const discountTypeOptions = [
 95→  { label: "Percentage (%)", value: "percentage" },
 96→  { label: "Fixed amount ($)", value: "fixed" },
 97→];
 98→
 99→const productLimitOptions = Array.from({ length: 10 }, (_, i) => ({
100→  label: String(i + 1),
101→  value: String(i + 1),
102→}));
103→
104→function typeBadgeTone(
105→  type: string
106→): "info" | "success" | "attention" | undefined {
107→  if (type === "score-range") return "info";
108→  if (type === "tag-match") return "success";
109→  return undefined;
110→}
111→
112→function typeBadgeLabel(type: string): string {
113→  if (type === "score-range") return "Score Range";
114→  if (type === "tag-match") return "Tag Match";
115→  return "Default";
116→}
117→
118→// ─── Loader ───────────────────────────────────────────────────────────────────
119→
120→export const loader = async ({ request, params }: LoaderFunctionArgs) => {
121→  const { session } = await authenticate.admin(request);
122→  const quizId = params.id;
123→
124→  if (!quizId) {
125→    throw data({ error: "Missing quiz ID" }, { status: 400 });
126→  }
127→
128→  try {
129→    const quiz = await db.quiz.findFirst({
130→      where: { id: quizId, shop: session.shop },
131→      include: {
132→        resultPages: { orderBy: { position: "asc" } },
133→      },
134→    });
135→
136→    if (!quiz) {
137→      throw data({ error: "Quiz not found" }, { status: 404 });
138→    }
139→
140→    const resultPages: ResultPageData[] = quiz.resultPages.map((r) => ({
141→      id: r.id,
142→      quizId: r.quizId,
143→      title: r.title,
144→      description: r.description,
145→      type: r.type,
146→      minScore: r.minScore,
147→      maxScore: r.maxScore,
148→      matchTags: parseSafe<string[]>(r.matchTags, []),
149→      productLimit: r.productLimit,
150→      layout: r.layout,
151→      showDiscount: r.showDiscount,
152→      discountType: r.discountType,
153→      discountValue: r.discountValue,
154→      discountCode: r.discountCode,
155→      ctaText: r.ctaText,
156→      ctaUrl: r.ctaUrl,
157→      styling: parseSafe<Record<string, unknown>>(r.styling, {}),
158→      position: r.position,
159→      createdAt: r.createdAt.toISOString(),
160→      updatedAt: r.updatedAt.toISOString(),
161→    }));
162→
163→    return {
164→      quiz: {
165→        id: quiz.id,
166→        title: quiz.title,
167→        status: quiz.status,
168→      },
169→      resultPages,
170→    } as LoaderData;
171→  } catch (error) {
172→    if (error instanceof Response) throw error;
173→    throw data({ error: "Failed to load result pages" }, { status: 500 });
174→  }
175→};
176→
177→// ─── Action ───────────────────────────────────────────────────────────────────
178→
179→export const action = async ({ request, params }: ActionFunctionArgs) => {
180→  const { session } = await authenticate.admin(request);
181→  const quizId = params.id!;
182→  const formData = await request.formData();
183→  const intent = String(formData.get("intent") ?? "");
184→
185→  try {
186→    // Verify quiz ownership before any mutation
187→    const quiz = await db.quiz.findFirst({
188→      where: { id: quizId, shop: session.shop },
189→    });
190→    if (!quiz) {
191→      return data({ error: "Quiz not found" }, { status: 404 });
192→    }
193→
194→    switch (intent) {
195→      case "create": {
196→        const title = String(formData.get("title") ?? "Result Page").trim() || "Result Page";
197→        const type = String(formData.get("type") ?? "default");
198→        const count = await db.resultPage.count({ where: { quizId } });
199→        await db.resultPage.create({
200→          data: {
201→            quizId,
202→            title,
203→            type,
204→            position: count,
205→          },
206→        });
207→        return { success: true, message: "Result page created." };
208→      }
209→
210→      case "update": {
211→        const pageId = String(formData.get("pageId") ?? "").trim();
212→        if (!pageId) {
213→          return data({ error: "Missing page ID" }, { status: 400 });
214→        }
215→
216→        // Verify page belongs to this quiz (which we already confirmed belongs to shop)
217→        const existingPage = await db.resultPage.findFirst({
218→          where: { id: pageId, quizId },
219→        });
220→        if (!existingPage) {
221→          return data({ error: "Result page not found" }, { status: 404 });
222→        }
223→
224→        const title = String(formData.get("title") ?? "").trim();
225→        const description = String(formData.get("description") ?? "").trim() || null;
226→        const type = String(formData.get("type") ?? "default");
227→        const layout = String(formData.get("layout") ?? "grid");
228→        const productLimit = parseInt(String(formData.get("productLimit") ?? "4"), 10);
229→        const showDiscount = formData.get("showDiscount") === "true";
230→        const ctaText = String(formData.get("ctaText") ?? "").trim() || null;
231→        const ctaUrl = String(formData.get("ctaUrl") ?? "").trim() || null;
232→
233→        // Score-range fields
234→        const minScoreRaw = formData.get("minScore");
235→        const maxScoreRaw = formData.get("maxScore");
236→        const minScore =
237→          minScoreRaw !== null && String(minScoreRaw).trim() !== ""
238→            ? parseInt(String(minScoreRaw), 10)
239→            : null;
240→        const maxScore =
241→          maxScoreRaw !== null && String(maxScoreRaw).trim() !== ""
242→            ? parseInt(String(maxScoreRaw), 10)
243→            : null;
244→
245→        // Tag-match fields
246→        const matchTagsRaw = String(formData.get("matchTags") ?? "")
247→          .split(",")
248→          .map((t) => t.trim())
249→          .filter(Boolean);
250→        const matchTags = JSON.stringify(matchTagsRaw);
251→
252→        // Discount fields
253→        const discountType = showDiscount
254→          ? String(formData.get("discountType") ?? "percentage") || null
255→          : null;
256→        const discountValueRaw = formData.get("discountValue");
257→        const discountValue =
258→          showDiscount && discountValueRaw !== null && String(discountValueRaw).trim() !== ""
259→            ? parseFloat(String(discountValueRaw))
260→            : null;
261→        const discountCode = showDiscount
262→          ? String(formData.get("discountCode") ?? "").trim() || null
263→          : null;
264→
265→        if (!title) {
266→          return data({ error: "Title is required" }, { status: 400 });
267→        }
268→
269→        await db.resultPage.update({
270→          where: { id: pageId },
271→          data: {
272→            title,
273→            description,
274→            type,
275→            minScore: type === "score-range" ? minScore : null,
276→            maxScore: type === "score-range" ? maxScore : null,
277→            matchTags: type === "tag-match" ? matchTags : "[]",
278→            layout,
279→            productLimit: isNaN(productLimit) ? 4 : productLimit,
280→            showDiscount,
281→            discountType,
282→            discountValue,
283→            discountCode,
284→            ctaText,
285→            ctaUrl,
286→            updatedAt: new Date(),
287→          },
288→        });
289→
290→        return { success: true, message: "Result page saved." };
291→      }
292→
293→      case "delete": {
294→        const pageId = String(formData.get("pageId") ?? "").trim();
295→        if (!pageId) {
296→          return data({ error: "Missing page ID" }, { status: 400 });
297→        }
298→
299→        // Verify page belongs to this quiz
300→        const page = await db.resultPage.findFirst({
301→          where: { id: pageId, quizId },
302→        });
303→        if (!page) {
304→          return data({ error: "Result page not found" }, { status: 404 });
305→        }
306→
307→        await db.resultPage.delete({ where: { id: pageId } });
308→
309→        // Re-index positions after delete
310→        const remaining = await db.resultPage.findMany({
311→          where: { quizId },
312→          orderBy: { position: "asc" },
313→        });
314→        await Promise.all(
315→          remaining.map((p, idx) =>
316→            db.resultPage.update({ where: { id: p.id }, data: { position: idx } })
317→          )
318→        );
319→
320→        return { success: true, message: "Result page deleted." };
321→      }
322→
323→      case "reorder": {
324→        const orderJson = String(formData.get("order") ?? "[]");
325→        let order: string[];
326→        try {
327→          order = JSON.parse(orderJson) as string[];
328→        } catch {
329→          return data({ error: "Invalid order data" }, { status: 400 });
330→        }
331→        await Promise.all(
332→          order.map((pageId, idx) =>
333→            db.resultPage.updateMany({
334→              where: { id: pageId, quizId },
335→              data: { position: idx },
336→            })
337→          )
338→        );
339→        return { success: true, message: "Order updated." };
340→      }
341→
342→      default:
343→        return data({ error: "Unknown action" }, { status: 400 });
344→    }
345→  } catch (error) {
346→    if (error instanceof Response) throw error;
347→    console.error(`Results action "${intent}" failed:`, error);
348→    return data({ error: "Action failed. Please try again." }, { status: 500 });
349→  }
350→};
351→
352→// ─── Action response type (for fetcher casting) ───────────────────────────────
353→
354→type ActionResponse =
355→  | { success: true; message: string }
356→  | { error: string };
357→
358→// ─── Edit Panel ───────────────────────────────────────────────────────────────
359→
360→interface EditPanelProps {
361→  page: ResultPageData;
362→  onDelete: (pageId: string) => void;
363→  isSaving: boolean;
364→}
365→
366→function EditPanel({ page, onDelete, isSaving }: EditPanelProps) {
367→  const fetcher = useFetcher<typeof action>() as {
368→    data: ActionResponse | undefined;
369→    state: "idle" | "loading" | "submitting";
370→    submit: (data: FormData, options: { method: string }) => void;
371→  };
372→
373→  const [title, setTitle] = useState(page.title);
374→  const [description, setDescription] = useState(page.description ?? "");
375→  const [type, setType] = useState(page.type);
376→  const [minScore, setMinScore] = useState(
377→    page.minScore !== null ? String(page.minScore) : ""
378→  );
379→  const [maxScore, setMaxScore] = useState(
380→    page.maxScore !== null ? String(page.maxScore) : ""
381→  );
382→  const [matchTags, setMatchTags] = useState(page.matchTags.join(", "));
383→  const [layout, setLayout] = useState(page.layout);
384→  const [productLimit, setProductLimit] = useState(String(page.productLimit));
385→  const [showDiscount, setShowDiscount] = useState(page.showDiscount);
386→  const [discountType, setDiscountType] = useState(
387→    page.discountType ?? "percentage"
388→  );
389→  const [discountValue, setDiscountValue] = useState(
390→    page.discountValue !== null ? String(page.discountValue) : ""
391→  );
392→  const [discountCode, setDiscountCode] = useState(page.discountCode ?? "");
393→  const [ctaText, setCtaText] = useState(page.ctaText ?? "");
394→  const [ctaUrl, setCtaUrl] = useState(page.ctaUrl ?? "");
395→
396→  // Reset local state when page selection changes
397→  useEffect(() => {
398→    setTitle(page.title);
399→    setDescription(page.description ?? "");
400→    setType(page.type);
401→    setMinScore(page.minScore !== null ? String(page.minScore) : "");
402→    setMaxScore(page.maxScore !== null ? String(page.maxScore) : "");
403→    setMatchTags(page.matchTags.join(", "));
404→    setLayout(page.layout);
405→    setProductLimit(String(page.productLimit));
406→    setShowDiscount(page.showDiscount);
407→    setDiscountType(page.discountType ?? "percentage");
408→    setDiscountValue(page.discountValue !== null ? String(page.discountValue) : "");
409→    setDiscountCode(page.discountCode ?? "");
410→    setCtaText(page.ctaText ?? "");
411→    setCtaUrl(page.ctaUrl ?? "");
412→  }, [page.id]); // eslint-disable-line react-hooks/exhaustive-deps
413→
414→  // Toast from fetcher (inline save)
415→  useEffect(() => {
416→    if (!fetcher.data) return;
417→    if ("success" in fetcher.data && fetcher.data.success && "message" in fetcher.data) {
418→      showToast(String(fetcher.data.message), { duration: 3000 });
419→    } else if ("error" in fetcher.data && fetcher.data.error) {
420→      showToast(String(fetcher.data.error), { duration: 4000, isError: true });
421→    }
422→  }, [fetcher.data]);
423→
424→  const handleSave = useCallback(() => {
425→    const fd = new FormData();
426→    fd.set("intent", "update");
427→    fd.set("pageId", page.id);
428→    fd.set("title", title);
429→    fd.set("description", description);
430→    fd.set("type", type);
431→    fd.set("minScore", minScore);
432→    fd.set("maxScore", maxScore);
433→    fd.set("matchTags", matchTags);
434→    fd.set("layout", layout);
435→    fd.set("productLimit", productLimit);
436→    fd.set("showDiscount", String(showDiscount));
437→    fd.set("discountType", discountType);
438→    fd.set("discountValue", discountValue);
439→    fd.set("discountCode", discountCode);
440→    fd.set("ctaText", ctaText);
441→    fd.set("ctaUrl", ctaUrl);
442→    fetcher.submit(fd, { method: "POST" });
443→  }, [
444→    fetcher,
445→    page.id,
446→    title,
447→    description,
448→    type,
449→    minScore,
450→    maxScore,
451→    matchTags,
452→    layout,
453→    productLimit,
454→    showDiscount,
455→    discountType,
456→    discountValue,
457→    discountCode,
458→    ctaText,
459→    ctaUrl,
460→  ]);
461→
462→  return (
463→    <Card>
464→      <BlockStack gap="400">
465→        <InlineStack align="space-between" blockAlign="center">
466→          <Text as="h3" variant="headingSm" fontWeight="semibold">
467→            Edit result page
468→          </Text>
469→          <Badge tone={typeBadgeTone(type)}>{typeBadgeLabel(type)}</Badge>
470→        </InlineStack>
471→
472→        <Divider />
473→
474→        <FormLayout>
475→          <TextField
476→            label="Title"
477→            value={title}
478→            onChange={setTitle}
479→            autoComplete="off"
480→            requiredIndicator
481→          />
482→          <TextField
483→            label="Description"
484→            value={description}
485→            onChange={setDescription}
486→            autoComplete="off"
487→            multiline={3}
488→          />
489→          <Select
490→            label="Result page type"
491→            options={typeOptions}
492→            value={type}
493→            onChange={setType}
494→          />
495→
496→          {type === "score-range" && (
497→            <FormLayout.Group>
498→              <TextField
499→                label="Minimum score"
500→                type="number"
501→                value={minScore}
502→                onChange={setMinScore}
503→                autoComplete="off"
504→                placeholder="0"
505→              />
506→              <TextField
507→                label="Maximum score"
508→                type="number"
509→                value={maxScore}
510→                onChange={setMaxScore}
511→                autoComplete="off"
512→                placeholder="100"
513→              />
514→            </FormLayout.Group>
515→          )}
516→
517→          {type === "tag-match" && (
518→            <TextField
519→              label="Match tags (comma-separated)"
520→              value={matchTags}
521→              onChange={setMatchTags}
522→              autoComplete="off"
523→              placeholder="skincare, sensitive, dry"
524→              helpText="Shoppers whose answers match these product tags will see this result page."
525→            />
526→          )}
527→
528→          <Select
529→            label="Product display layout"
530→            options={layoutOptions}
531→            value={layout}
532→            onChange={setLayout}
533→          />
534→
535→          <Select
536→            label="Product limit"
537→            options={productLimitOptions}
538→            value={productLimit}
539→            onChange={setProductLimit}
540→          />
541→
542→          <Checkbox
543→            label="Show discount"
544→            checked={showDiscount}
545→            onChange={setShowDiscount}
546→            helpText="Display a discount code on this result page."
547→          />
548→
549→          {showDiscount && (
550→            <>
551→              <FormLayout.Group>
552→                <Select
553→                  label="Discount type"
554→                  options={discountTypeOptions}
555→                  value={discountType}
556→                  onChange={setDiscountType}
557→                />
558→                <TextField
559→                  label="Discount value"
560→                  type="number"
561→                  value={discountValue}
562→                  onChange={setDiscountValue}
563→                  autoComplete="off"
564→                  placeholder={discountType === "percentage" ? "10" : "5.00"}
565→                  suffix={discountType === "percentage" ? "%" : "$"}
566→                />
567→              </FormLayout.Group>
568→              <TextField
569→                label="Discount code"
570→                value={discountCode}
571→                onChange={setDiscountCode}
572→                autoComplete="off"
573→                placeholder="QUIZSNAP10"
574→                helpText="The actual Shopify discount code shoppers will apply at checkout."
575→              />
576→            </>
577→          )}
578→
579→          <Divider />
580→
581→          <TextField
582→            label="CTA button text"
583→            value={ctaText}
584→            onChange={setCtaText}
585→            autoComplete="off"
586→            placeholder="Shop Now"
587→          />
588→          <TextField
589→            label="CTA button URL"
590→            value={ctaUrl}
591→            onChange={setCtaUrl}
592→            autoComplete="off"
593→            placeholder="https://your-store.myshopify.com/collections/all"
594→            helpText="Leave blank to use the recommended products link."
595→          />
596→        </FormLayout>
597→
598→        <Divider />
599→
600→        <InlineStack align="space-between">
601→          <Button
602→            tone="critical"
603→            variant="plain"
604→            onClick={() => onDelete(page.id)}
605→          >
606→            Delete result page
607→          </Button>
608→          <Button
609→            variant="primary"
610→            onClick={handleSave}
611→            loading={isSaving || fetcher.state !== "idle"}
612→          >
613→            Save changes
614→          </Button>
615→        </InlineStack>
616→      </BlockStack>
617→    </Card>
618→  );
619→}
