642→// ─── Main Page ────────────────────────────────────────────────────────────────
643→
644→export default function ResultPagesEditor() {
645→  const loaderResult = useLoaderData<typeof loader>() as unknown as LoaderData;
646→  const { quiz, resultPages } = loaderResult;
647→  const actionData = useActionData<typeof action>() as ActionResponse | undefined;
648→  const fetcher = useFetcher<typeof action>() as {
649→    data: ActionResponse | undefined;
650→    state: "idle" | "loading" | "submitting";
651→    submit: (data: FormData, options: { method: string }) => void;
652→  };
653→
654→  const [selectedPageId, setSelectedPageId] = useState<string | null>(
655→    resultPages.length > 0 ? resultPages[0].id : null
656→  );
657→  const [deleteModalOpen, setDeleteModalOpen] = useState(false);
658→  const [pendingDeleteId, setPendingDeleteId] = useState<string | null>(null);
659→  const [createModalOpen, setCreateModalOpen] = useState(false);
660→  const [newPageTitle, setNewPageTitle] = useState("");
661→  const [newPageType, setNewPageType] = useState("default");
662→
663→  const selectedPage = resultPages.find((p) => p.id === selectedPageId) ?? null;
664→
665→  // IndexTable resource state (for row selection highlight)
666→  const { selectedResources, allResourcesSelected, handleSelectionChange } =
667→    useIndexResourceState(resultPages.map((p) => ({ id: p.id })));
668→
669→  // Toast from page-level action (create / delete / reorder)
670→  useEffect(() => {
671→    if (!actionData) return;
672→    if ("success" in actionData && actionData.success && "message" in actionData) {
673→      showToast(String(actionData.message), { duration: 3000 });
674→    } else if ("error" in actionData && actionData.error) {
675→      showToast(String(actionData.error), { duration: 4000, isError: true });
676→    }
677→  }, [actionData]);
678→
679→  // Auto-select first page after new creation (resultPages re-loads via loader)
680→  useEffect(() => {
