  3→function slugify(text: string): string {
  4→  return (
  5→    text
  6→      .toLowerCase()
  7→      .replace(/[^a-z0-9\s-]/g, "")
  8→      .replace(/\s+/g, "-")
  9→      .replace(/-+/g, "-")
 10→      .replace(/^-|-$/g, "") || "quiz"
 11→  );
 12→}
 13→
 14→async function generateUniqueSlug(
 15→  shop: string,
 16→  title: string,
 17→  excludeId?: string
 18→): Promise<string> {
 19→  const base = slugify(title);
 20→  let slug = base;
 21→  let counter = 0;
 22→  while (true) {
 23→    const existing = await db.quiz.findFirst({
 24→      where: {
 25→        shop,
 26→        slug,
 27→        ...(excludeId ? { NOT: { id: excludeId } } : {}),
 28→      },
 29→    });
 30→    if (!existing) break;
 31→    counter++;
 32→    slug = `${base}-${counter}`;
 33→  }
 34→  return slug;
 35→}
