 37→export interface QuizCreateInput {
 38→  title: string;
 39→  type?: string;
 40→  description?: string;
 41→}
 42→
 43→export function validateQuizCreate(input: QuizCreateInput): ValidationResult {
 44→  const errors: ValidationError[] = [];
 45→
 46→  if (!input.title || input.title.trim().length === 0) {
 47→    errors.push(err("title", "Title is required"));
 48→  } else if (input.title.trim().length > 255) {
 49→    errors.push(err("title", "Title must be 255 characters or fewer"));
 50→  }
 51→
 52→  if (input.type && !(QUIZ_TYPES as readonly string[]).includes(input.type)) {
 53→    errors.push(err("type", `Type must be one of: ${QUIZ_TYPES.join(", ")}`));
 54→  }
 55→
 56→  if (input.description && input.description.length > 1000) {
 57→    errors.push(err("description", "Description must be 1000 characters or fewer"));
 58→  }
 59→
 60→  return { valid: errors.length === 0, errors };
 61→}
