 80→  }
 81→
 82→  if (input.description !== undefined && input.description.length > 1000) {
 83→    errors.push(err("description", "Description must be 1000 characters or fewer"));
 84→  }
 85→
 86→  if (input.status !== undefined && !(QUIZ_STATUSES as readonly string[]).includes(input.status)) {
 87→    errors.push(err("status", `Status must be one of: ${QUIZ_STATUSES.join(", ")}`));
