162→
163→export function validateAnswerCreate(input: AnswerCreateInput): ValidationResult {
164→  const errors: ValidationError[] = [];
165→
166→  if (!input.questionId || input.questionId.trim().length === 0) {
167→    errors.push(err("questionId", "Question ID is required"));
168→  }
169→
170→  if (!input.text || input.text.trim().length === 0) {
171→    errors.push(err("text", "Answer text is required"));
172→  } else if (input.text.trim().length > 255) {
173→    errors.push(err("text", "Answer text must be 255 characters or fewer"));
174→  }
175→
176→  if (input.score !== undefined) {
177→    if (!Number.isInteger(input.score)) {
