189→export function validateEmail(email: string): string | null {
190→  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
191→  if (!emailRegex.test(email)) {
192→    return "Please enter a valid email address";
193→  }
194→  return null;
195→}
