198→
199→export function errorsToMap(errors: ValidationError[]): Record<string, string> {
200→  return errors.reduce<Record<string, string>>((acc, e) => {
201→    if (!acc[e.field]) acc[e.field] = e.message;
202→    return acc;
203→  }, {});
204→}
