114→// --- Loader ---
115→
116→export const loader = async ({ request, params }: LoaderFunctionArgs) => {
117→  const { session } = await authenticate.admin(request);
118→  const quizId = params.id;
119→
120→  if (!quizId) {
121→    throw data({ error: "Missing quiz ID" }, { status: 400 });
122→  }
123→
124→  try {
125→    const quiz = await db.quiz.findFirst({
126→      where: { id: quizId, shop: session.shop },
127→      include: {
128→        questions: {
129→          include: { answers: { orderBy: { position: "asc" } } },
130→          orderBy: { position: "asc" },
131→        },
132→      },
133→    });
134→
135→    if (!quiz) {
136→      throw data({ error: "Quiz not found" }, { status: 404 });
137→    }
138→
139→    const stylingObj = parseSafe<{
140→      buttonColor?: string;
141→      buttonText?: string;
142→      resultsHeading?: string;
143→      showProgressBar?: boolean;
144→    }>(quiz.styling, {});
145→
146→    const designSettings: DesignSettings = {
147→      quizTitle: quiz.title,
148→      description: quiz.description ?? "",
149→      buttonColor: stylingObj.buttonColor ?? "#5C6AC4",
150→      buttonText: stylingObj.buttonText ?? "Next",
151→      resultsHeading: stylingObj.resultsHeading ?? "Your Results",
152→      showProgressBar: stylingObj.showProgressBar ?? true,
153→    };
154→
155→    const questions: Question[] = quiz.questions.map((q) => ({
156→      id: q.id,
157→      title: q.title,
158→      type: q.type,
159→      required: q.required,
160→      position: q.position,
161→      options: q.answers.map((a) => ({
162→        id: a.id,
163→        label: a.text,
164→        score: a.score,
165→        productTags: parseSafe(a.productTags, [] as string[]),
166→        position: a.position,
167→      })),
168→    }));
169→
170→    return {
171→      quiz: {
172→        id: quiz.id,
173→        title: quiz.title,
174→        description: quiz.description,
175→        slug: quiz.slug,
176→        status: quiz.status,
177→        settings: quiz.settings,
178→        styling: quiz.styling,
179→      },
180→      questions,
181→      designSettings,
182→    } as LoaderData;
183→  } catch (error) {
184→    if (error instanceof Response) throw error;
185→    throw data({ error: "Failed to load quiz" }, { status: 500 });
186→  }
187→};
