189→// --- Action ---
190→
191→export const action = async ({ request, params }: ActionFunctionArgs) => {
192→  const { session } = await authenticate.admin(request);
193→  const quizId = params.id!;
194→  const formData = await request.formData();
195→  const intent = String(formData.get("intent") ?? "");
196→
197→  try {
198→    // Verify ownership before any mutation
199→    const quiz = await db.quiz.findFirst({
200→      where: { id: quizId, shop: session.shop },
201→    });
202→    if (!quiz) {
203→      return data({ error: "Quiz not found" }, { status: 404 });
204→    }
205→
206→    switch (intent) {
207→      case "save-design": {
208→        const title = String(formData.get("title") ?? "").trim();
209→        const description =
210→          String(formData.get("description") ?? "").trim() || null;
211→        const styling = String(formData.get("styling") ?? "{}");
212→        if (!title) {
213→          return data({ error: "Title is required" }, { status: 400 });
214→        }
215→        await db.quiz.update({
216→          where: { id: quizId },
217→          data: { title, description, styling, updatedAt: new Date() },
218→        });
219→        return { success: true, message: "Design saved!" };
220→      }
221→
222→      case "publish": {
223→        await db.quiz.update({
224→          where: { id: quizId },
225→          data: {
226→            status: "active",
227→            publishedAt: quiz.publishedAt ?? new Date(),
228→          },
229→        });
230→        return {
231→          success: true,
232→          message: "Quiz published! It's now live on your storefront.",
233→        };
234→      }
235→
236→      case "unpublish": {
237→        await db.quiz.update({
238→          where: { id: quizId },
239→          data: { status: "draft" },
240→        });
241→        return { success: true, message: "Quiz unpublished." };
242→      }
243→
244→      case "delete": {
245→        await db.quiz.delete({ where: { id: quizId } });
246→        return redirect("/app/quizzes");
247→      }
248→
249→      case "save-questions": {
250→        const questionsJson = String(formData.get("questions") ?? "[]");
251→        let questions: Array<{
252→          id?: string;
253→          title: string;
254→          type: string;
255→          required: boolean;
256→          position: number;
257→          options: Array<{
258→            id?: string;
259→            label: string;
260→            score: number;
261→            productTags: string[];
262→            position: number;
263→          }>;
264→        }>;
265→
266→        try {
267→          questions = JSON.parse(questionsJson);
268→        } catch {
269→          return data({ error: "Invalid questions data" }, { status: 400 });
270→        }
271→
272→        // Delete all existing questions (cascade deletes answers)
273→        await db.question.deleteMany({ where: { quizId } });
274→
275→        // Re-create all questions with their answers
276→        for (const q of questions) {
277→          await db.question.create({
278→            data: {
279→              quizId,
280→              title: q.title,
281→              type: q.type,
282→              required: q.required,
283→              position: q.position,
284→              answers: {
285→                create: q.options.map((a) => ({
286→                  text: a.label,
287→                  score: a.score,
288→                  productTags: JSON.stringify(a.productTags),
289→                  position: a.position,
290→                })),
291→              },
292→            },
293→          });
294→        }
295→        return { success: true, message: "Questions saved!" };
296→      }
297→
298→      default:
299→        return data({ error: "Unknown action" }, { status: 400 });
300→    }
301→  } catch (error) {
302→    if (error instanceof Response) throw error;
303→    console.error(`Quiz action "${intent}" failed:`, error);
304→    return data(
305→      { error: "Action failed. Please try again." },
306→      { status: 500 },
307→    );
308→  }
309→};
