1182→        prev.map((q) =>
1183→          q.id === questionId
1184→            ? {
1185→                ...q,
1186→                options: q.options.map((opt) =>
1187→                  opt.id === optionId
1188→                    ? {
1189→                        ...opt,
1190→                        productTags: opt.productTags.filter((t) => t !== tag),
1191→                      }
1192→                    : opt,
1193→                ),
1194→              }
1195→            : q,
1196→        ),
1197→      );
1198→    },
1199→    [],

1200→  );
1201→
1202→  // --- Design handlers ---
1203→
1204→  const handleUpdateDesign = useCallback(
